definition.script:
pipeline {
  agent any
  options { timestamps(); disableConcurrentBuilds(); buildDiscarder(logRotator(numToKeepStr: '20')) }
  stages {
    stage('Refresh branch cache') {
      steps {
        sh '''
          set -euo pipefail
          export JENKINS_HOME_JOBS=/var/jenkins_home/jobs
          export GITEE_FREEDOM=/gitee/wealth-freedom
          export GITEE_WEB=/gitee/wealth-freedom-web
          export GITEE_MALL=/gitee/wealth-ecommerce-web
          bash /jenkins-backup/scripts/refresh-branch-cache.sh
        '''
      }
    }
  }
  post {
    success { echo '分支缓存已更新。请重新打开各模块 Build with Parameters 查看 BRANCH 下拉。' }
    failure { echo '失败时检查：github-ssh / 容器内 SSH 私钥、网络、/gitee 挂载' }
  }
}
